head.b:skin:
/*--------------------------------------------------
Blogger Template Name: VideoHub LK Premium
Author: AI Assistant
URL: https://ai.studio/build
--------------------------------------------------*/

/* Reset and Core Styles */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: #0A0F1D;
  color: #FFFFFF;
  font-family: 'Inter', sans-serif;
  line-height: 1.5;
  font-size: 15px;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: all 0.2s ease-in-out;
}

a:hover {
  color: #0066FF;
}

img {
  max-width: 100%;
  height: auto;
}

/* Container layout */
.vh-container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1rem;
}

/* Sticky Header styles */
header.vh-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background-color: #121829;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(12px);
}

.header-wrapper {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}

.logo-area {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  font-size: 1.5rem;
  color: #FFFFFF;
}

.logo-area span.highlight {
  color: #0066FF;
}

.logo-area span.badge {
  color: #FF3366;
  font-size: 1.5rem;
}

.header-search {
  display: none;
  flex: 1;
  max-width: 500px;
  margin: 0 2rem;
}

@media (min-width: 768px) {
  .header-search {
    display: block;
  }
}

.search-form {
  position: relative;
  width: 100%;
}

.search-form input {
  width: 100%;
  background-color: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 9999px;
  padding: 0.6rem 1.2rem 0.6rem 2.8rem;
  color: white;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s;
}

.search-form input:focus {
  border-color: #0066FF;
  background-color: rgba(255, 255, 255, 0.08);
}

.search-form .search-icon {
  position: absolute;
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: #94A3B8;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.btn-upload {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: linear-gradient(135deg, #0066FF 0%, #1d4ed8 100%);
  color: white;
  font-weight: 600;
  padding: 0.5rem 1.2rem;
  border-radius: 8px;
  font-size: 0.875rem;
  box-shadow: 0 4px 12px rgba(0, 102, 255, 0.3);
}

.btn-upload:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(0, 102, 255, 0.4);
}

.mobile-menu-toggle {
  background: none;
  border: none;
  color: white;
  font-size: 1.5rem;
  cursor: pointer;
  display: block;
}

@media (min-width: 1024px) {
  .mobile-menu-toggle {
    display: none;
  }
}

/* Navigation Menu */
.navigation-bar {
  background-color: rgba(0, 0, 0, 0.2);
  border-bottom: 1px solid rgba(255, 255, 255, 0.03);
}

.nav-menu {
  display: none;
  list-style: none;
  align-items: center;
  gap: 1.5rem;
  height: 50px;
}

@media (min-width: 1024px) {
  .nav-menu {
    display: flex;
  }
}

.nav-item a {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: #94A3B8;
}

.nav-item a:hover, .nav-item.active a {
  color: #FFFFFF;
}

.nav-item.active {
  position: relative;
}

.nav-item.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: #0066FF;
}

/* Mobile Navigation Drawer */
.mobile-nav-drawer {
  position: fixed;
  top: 0;
  left: -280px;
  width: 280px;
  height: 100vh;
  background-color: #121829;
  z-index: 2000;
  padding: 2rem 1.5rem;
  box-shadow: 10px 0 30px rgba(0,0,0,0.5);
  transition: left 0.3s ease-in-out;
}

.mobile-nav-drawer.active {
  left: 0;
}

.drawer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.drawer-close {
  background: none;
  border: none;
  color: white;
  font-size: 1.5rem;
  cursor: pointer;
}

.drawer-menu {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.drawer-item a {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 1.1rem;
  color: #94A3B8;
}

.drawer-item a:hover {
  color: white;
  padding-left: 5px;
}

.drawer-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(0,0,0,0.6);
  backdrop-filter: blur(4px);
  z-index: 1999;
  display: none;
}

.drawer-backdrop.active {
  display: block;
}

/* Advertisement Slots Styling */
.vh-ad-banner {
  background-color: rgba(255, 255, 255, 0.02);
  border: 1px dashed rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  padding: 1rem;
  text-align: center;
  color: #94A3B8;
  font-size: 0.75rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin: 1.5rem 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 90px;
  gap: 0.3rem;
}

.vh-ad-banner i {
  font-size: 1.2rem;
  color: rgba(255,255,255,0.2);
}

/* Hero Featured Section */
.hero-section {
  padding: 2rem 0;
  background: radial-gradient(circle at top right, rgba(0,102,255,0.08), transparent 45%);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 1024px) {
  .hero-grid {
    grid-template-columns: 2fr 1fr;
  }
}

/* Big Featured Player Banner */
.featured-banner {
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  aspect-ratio: 16/9;
  box-shadow: 0 10px 30px rgba(0,0,0,0.4);
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.featured-banner img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.featured-banner:hover img {
  transform: scale(1.03);
}

.featured-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(10, 15, 29, 0.95) 0%, rgba(10, 15, 29, 0.4) 60%, transparent 100%);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 1.5rem;
}

@media (min-width: 768px) {
  .featured-overlay {
    padding: 2.5rem;
  }
}

.badge-category {
  background-color: #0066FF;
  color: white;
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  width: fit-content;
  margin-bottom: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-category.sports {
  background-color: #FF3366;
}

.featured-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 0.5rem;
}

@media (min-width: 768px) {
  .featured-title {
    font-size: 2rem;
  }
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: 0.825rem;
  color: #94A3B8;
  margin-bottom: 1rem;
}

.featured-meta span {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.btn-play-hero {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background-color: #FFFFFF;
  color: #0A0F1D;
  font-weight: 700;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  width: fit-content;
  transition: background-color 0.2s, transform 0.2s;
}

.btn-play-hero:hover {
  background-color: #0066FF;
  color: white;
  transform: translateY(-2px);
}

/* Right Sidebar/Trending Slider List */
.trending-list-container {
  display: flex;
  flex-direction: column;
  background-color: #161F38;
  border-radius: 16px;
  padding: 1.5rem;
  border: 1px solid rgba(255,255,255,0.04);
  height: 100%;
}

.section-subtitle {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border-bottom: 2px solid rgba(255, 255, 255, 0.05);
  padding-bottom: 0.5rem;
}

.section-subtitle i {
  color: #FF3366;
}

.trending-mini-cards {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  overflow-y: auto;
  max-height: 380px;
  padding-right: 0.25rem;
}

/* Custom scrollbar */
.trending-mini-cards::-webkit-scrollbar {
  width: 4px;
}
.trending-mini-cards::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.1);
  border-radius: 4px;
}

.mini-card {
  display: flex;
  gap: 0.75rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid rgba(255,255,255,0.03);
}

.mini-card:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.mini-thumb {
  width: 100px;
  height: 60px;
  border-radius: 6px;
  overflow: hidden;
  position: relative;
  flex-shrink: 0;
}

.mini-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.mini-duration {
  position: absolute;
  bottom: 4px;
  right: 4px;
  background-color: rgba(0,0,0,0.8);
  color: white;
  font-size: 0.65rem;
  padding: 1px 4px;
  border-radius: 3px;
  font-weight: 600;
}

.mini-content {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.mini-title {
  font-size: 0.85rem;
  font-weight: 600;
  line-height: 1.3;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 0.2rem;
}

.mini-title:hover {
  color: #0066FF;
}

.mini-meta {
  font-size: 0.75rem;
  color: #94A3B8;
}

/* Content Grid (Main post feed & sidebar) */
.main-body-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  padding: 1.5rem 0 3rem 0;
}

@media (min-width: 1024px) {
  .main-body-grid {
    grid-template-columns: 2fr 1fr;
  }
}

/* Main content wrapper */
.feed-wrapper {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid rgba(255, 255, 255, 0.05);
  padding-bottom: 0.5rem;
  margin-bottom: 1.5rem;
}

.section-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  position: relative;
}

.section-title::after {
  content: '';
  position: absolute;
  bottom: -0.6rem;
  left: 0;
  width: 60px;
  height: 3px;
  background-color: #0066FF;
}

/* Video Card Grid */
.video-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 640px) {
  .video-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Responsive Video Card */
.video-card {
  background-color: #161F38;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.04);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.15);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, box-shadow 0.2s;
}

.video-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
  border-color: rgba(255, 255, 255, 0.08);
}

.card-media {
  position: relative;
  aspect-ratio: 16/9;
  overflow: hidden;
  background-color: black;
}

.card-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.play-overlay {
  position: absolute;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.2s ease-in-out;
}

.video-card:hover .play-overlay {
  opacity: 1;
}

.play-icon-circle {
  width: 48px;
  height: 48px;
  background-color: #0066FF;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.25rem;
  box-shadow: 0 4px 12px rgba(0, 102, 255, 0.4);
  transform: scale(0.8);
  transition: transform 0.2s ease;
}

.video-card:hover .play-icon-circle {
  transform: scale(1);
}

.card-duration {
  position: absolute;
  bottom: 8px;
  right: 8px;
  background-color: rgba(10, 15, 29, 0.9);
  color: white;
  font-size: 0.75rem;
  padding: 2px 6px;
  border-radius: 4px;
  font-weight: 600;
  z-index: 2;
}

.card-category {
  position: absolute;
  top: 8px;
  left: 8px;
  background-color: rgba(0, 0, 0, 0.7);
  color: white;
  font-size: 0.65rem;
  padding: 2px 6px;
  border-radius: 4px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  z-index: 2;
  border: 1px solid rgba(255,255,255,0.1);
}

.card-body {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.card-title {
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 0.5rem;
  color: white;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  height: 2.8em;
}

.card-title:hover {
  color: #0066FF;
}

.card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
  color: #94A3B8;
  margin-bottom: 0.75rem;
}

.card-meta span {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.card-desc {
  font-size: 0.825rem;
  color: #94A3B8;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 1rem;
  line-height: 1.4;
  height: 2.8em;
}

.btn-watch-now {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  background-color: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  color: white;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 0.5rem;
  border-radius: 6px;
  text-align: center;
  margin-top: auto;
}

.btn-watch-now:hover {
  background-color: #0066FF;
  border-color: #0066FF;
  box-shadow: 0 4px 10px rgba(0, 102, 255, 0.2);
}

/* Sidebar widgets */
aside.vh-sidebar {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.sidebar-widget {
  background-color: #161F38;
  border-radius: 12px;
  padding: 1.5rem;
  border: 1px solid rgba(255, 255, 255, 0.04);
}

.widget-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 1.2rem;
  padding-bottom: 0.6rem;
  border-bottom: 2px solid rgba(255, 255, 255, 0.05);
  position: relative;
}

.widget-title::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 40px;
  height: 2px;
  background-color: #0066FF;
}

/* Popular Videos Widget items */
.popular-widget-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Social Follow Widget */
.social-follow-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

.social-follow-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.6rem;
  border-radius: 8px;
  font-size: 0.75rem;
  font-weight: 600;
  color: white;
}

.social-follow-btn.fb { background-color: #1877F2; }
.social-follow-btn.tw { background-color: #1DA1F2; }
.social-follow-btn.yt { background-color: #FF0000; }
.social-follow-btn.tg { background-color: #0088cc; }

.social-follow-btn:hover {
  transform: scale(1.02);
  opacity: 0.9;
}

/* Categories Widget List */
.categories-widget-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.categories-widget-list li a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.875rem;
  color: #94A3B8;
  padding: 0.4rem 0.6rem;
  border-radius: 6px;
  background-color: rgba(255,255,255,0.02);
}

.categories-widget-list li a:hover {
  background-color: rgba(255, 255, 255, 0.05);
  color: white;
  padding-left: 0.8rem;
}

.categories-widget-list .category-count {
  background-color: rgba(255,255,255,0.1);
  padding: 1px 6px;
  border-radius: 99px;
  font-size: 0.7rem;
  color: white;
}

/* Newsletter Subscription Widget */
.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.newsletter-form input {
  width: 100%;
  background-color: rgba(0, 0, 0, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  padding: 0.6rem 1rem;
  color: white;
  outline: none;
  font-size: 0.875rem;
}

.newsletter-form input:focus {
  border-color: #0066FF;
}

.newsletter-btn {
  background-color: #0066FF;
  color: white;
  border: none;
  border-radius: 8px;
  padding: 0.6rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
}

.newsletter-btn:hover {
  background-color: #1d4ed8;
}

/* Pagination Styles */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin: 2rem 0;
}

.page-link {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  height: 36px;
  padding: 0 0.5rem;
  background-color: #161F38;
  border: 1px solid rgba(255, 255, 255, 0.04);
  border-radius: 6px;
  font-size: 0.875rem;
  font-weight: 600;
  color: #94A3B8;
}

.page-link.active, .page-link:hover {
  background-color: #0066FF;
  border-color: #0066FF;
  color: white;
}

/* Single Video Page Styles */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8rem;
  color: #94A3B8;
  padding: 1rem 0;
}

.breadcrumb a:hover {
  color: #0066FF;
}

.video-player-container {
  position: relative;
  background-color: black;
  border-radius: 16px;
  overflow: hidden;
  aspect-ratio: 16/9;
  box-shadow: 0 8px 30px rgba(0,0,0,0.5);
  margin-bottom: 1.5rem;
  border: 1px solid rgba(255,255,255,0.05);
}

.video-player-container iframe, .video-player-container video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: none;
}

.video-details-box {
  background-color: #161F38;
  border-radius: 12px;
  padding: 1.5rem;
  border: 1px solid rgba(255,255,255,0.04);
  margin-bottom: 1.5rem;
}

.video-main-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.3rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 1rem;
}

@media (min-width: 768px) {
  .video-main-title {
    font-size: 1.75rem;
  }
}

.video-meta-bar {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  margin-bottom: 1rem;
}

@media (min-width: 768px) {
  .video-meta-bar {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.meta-left {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  font-size: 0.85rem;
  color: #94A3B8;
}

.meta-left span {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.video-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.btn-action {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  background-color: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 0.5rem 1rem;
  border-radius: 8px;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
}

.btn-action:hover {
  background-color: #0066FF;
  border-color: #0066FF;
  color: white;
}

.btn-action.download-btn {
  background-color: #FF3366;
  border-color: #FF3366;
  color: white;
}

.btn-action.download-btn:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

.video-description-content {
  font-size: 0.925rem;
  color: rgba(255, 255, 255, 0.8);
  line-height: 1.6;
  white-space: pre-line;
}

.video-tags-container {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

.tag-badge {
  background-color: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.06);
  color: #94A3B8;
  padding: 0.25rem 0.6rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 500;
}

.tag-badge:hover {
  color: white;
  background-color: rgba(255,255,255,0.08);
}

/* Related Videos List Grid */
.related-section {
  margin-bottom: 2rem;
}

/* Comment Section */
.comments-container {
  background-color: #161F38;
  border-radius: 12px;
  padding: 1.5rem;
  border: 1px solid rgba(255,255,255,0.04);
}

.comments-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.comments-form {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
}

.comment-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: #0066FF;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.9rem;
  flex-shrink: 0;
}

.comment-avatar img {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
}

.comment-input-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.comment-input-area textarea {
  width: 100%;
  background-color: rgba(0, 0, 0, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  color: white;
  font-family: inherit;
  outline: none;
  resize: none;
  height: 80px;
  font-size: 0.875rem;
}

.comment-input-area textarea:focus {
  border-color: #0066FF;
}

.btn-submit-comment {
  align-self: flex-end;
  background-color: #0066FF;
  color: white;
  border: none;
  border-radius: 8px;
  padding: 0.5rem 1.25rem;
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
}

.comment-item {
  display: flex;
  gap: 1rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid rgba(255,255,255,0.03);
  margin-bottom: 1.25rem;
}

.comment-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}

.comment-body {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.comment-user-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.comment-username {
  font-weight: 600;
  font-size: 0.875rem;
  color: white;
}

.comment-time {
  font-size: 0.75rem;
  color: #94A3B8;
}

.comment-text {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.85);
  line-height: 1.5;
}

/* Back to top button */
.back-to-top {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background-color: #0066FF;
  color: white;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 15px rgba(0,0,0,0.4);
  cursor: pointer;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
  z-index: 999;
}

.back-to-top.active {
  opacity: 1;
  visibility: visible;
}

.back-to-top:hover {
  transform: translateY(-4px);
  background-color: #FF3366;
}

/* Footer styling */
footer.vh-footer {
  background-color: #121829;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding: 4rem 0 2rem 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2.5rem;
  margin-bottom: 3rem;
}

@media (min-width: 640px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.footer-logo {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  font-size: 1.5rem;
  margin-bottom: 1rem;
  display: inline-block;
}

.footer-logo span {
  color: #0066FF;
}

.footer-about-text {
  font-size: 0.85rem;
  color: #94A3B8;
  line-height: 1.6;
  margin-bottom: 1.5rem;
}

.footer-social-icons {
  display: flex;
  gap: 0.75rem;
}

.footer-social-icons a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background-color: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.06);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 0.9rem;
}

.footer-social-icons a:hover {
  background-color: #0066FF;
  border-color: #0066FF;
  transform: translateY(-2px);
}

.footer-widget-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  position: relative;
  padding-bottom: 0.5rem;
}

.footer-widget-title::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 30px;
  height: 2px;
  background-color: #0066FF;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-links li a {
  font-size: 0.85rem;
  color: #94A3B8;
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.footer-links li a:hover {
  color: white;
  padding-left: 4px;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.05);
  padding-top: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
  }
}

.footer-copyright {
  font-size: 0.8rem;
  color: #94A3B8;
}

.footer-legal-links {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  font-size: 0.8rem;
  color: #94A3B8;
}

.footer-legal-links a:hover {
  color: white;
}

body.script:
//

// Drawer Open and Close controls
const openBtn = document.getElementById('openDrawerBtn');
const closeBtn = document.getElementById('closeDrawerBtn');
const drawer = document.getElementById('mobileDrawer');
const backdrop = document.getElementById('drawerBackdrop');

if (openBtn && closeBtn && drawer && backdrop) {
  openBtn.addEventListener('click', () => {
    drawer.classList.add('active');
    backdrop.classList.add('active');
  });

  const closeDrawer = () => {
    drawer.classList.remove('active');
    backdrop.classList.remove('active');
  };

  closeBtn.addEventListener('click', closeDrawer);
  backdrop.addEventListener('click', closeDrawer);
}

// Back to Top trigger
const bttBtn = document.getElementById('backToTopBtn');
window.addEventListener('scroll', () => {
  if (window.scrollY > 300) {
    bttBtn.classList.add('active');
  } else {
    bttBtn.classList.remove('active');
  }
});
if (bttBtn) {
  bttBtn.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
}

// Interactive responsive video generator for Blogger item pages
document.addEventListener('DOMContentLoaded', () => {
  const postBody = document.getElementById('mainBloggerPostContent');
  const playerContainer = document.getElementById('videoPlayerContainer');
  const fallbackPoster = document.getElementById('videoFallbackPoster');

  if (postBody && playerContainer) {
    // Look for raw video source links inside the blogger body content
    const textContent = postBody.innerHTML;
    let videoSrc = '';
    let type = '';

    // Match YouTube urls
    const ytMatch = textContent.match(/https:\/\/(?:www\.)?youtube\.com\/(?:watch\?v=|embed\/)([a-zA-Z0-9_-]{11})/i) ||
                   textContent.match(/https:\/\/youtu\.be\/([a-zA-Z0-9_-]{11})/i);

    // Match Vimeo urls
    const vimeoMatch = textContent.match(/https:\/\/(?:www\.)?vimeo\.com\/([0-9]+)/i) ||
                       textContent.match(/https:\/\/player\.vimeo\.com\/video\/([0-9]+)/i);

    // Match direct MP4 links
    const mp4Match = textContent.match(/https:\/\/[a-zA-Z0-9_\-\.\/\/]+\.mp4/i);

    if (ytMatch) {
      videoSrc = 'https://www.youtube.com/embed/' + ytMatch[1];
      type = 'youtube';
    } else if (vimeoMatch) {
      videoSrc = 'https://player.vimeo.com/video/' + vimeoMatch[1];
      type = 'vimeo';
    } else if (mp4Match) {
      videoSrc = mp4Match[0];
      type = 'mp4';
    }

    if (videoSrc) {
      // Hide preview thumbnail poster
      if (fallbackPoster) fallbackPoster.style.display = 'none';

      if (type === 'youtube' || type === 'vimeo') {
        const iframe = document.createElement('iframe');
        iframe.src = videoSrc + '?autoplay=1&mute=1';
        iframe.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture');
        iframe.setAttribute('allowfullscreen', 'true');
        playerContainer.appendChild(iframe);
      } else if (type === 'mp4') {
        const video = document.createElement('video');
        video.src = videoSrc;
        video.controls = true;
        video.autoplay = true;
        video.muted = true;
        playerContainer.appendChild(video);
      }
    }
  }
});

// Simple Share Buttons
function shareFacebook() {
  window.open('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(window.location.href), '_blank', 'width=600,height=400');
}

function shareTwitter() {
  window.open('https://twitter.com/intent/tweet?url=' + encodeURIComponent(window.location.href), '_blank', 'width=600,height=400');
}

function copyVideoUrl() {
  navigator.clipboard.writeText(window.location.href).then(() => {
    alert('Video Link copied to Clipboard successfully!');
  });
}

// Add a client-side mock blogger comment
function addBloggerComment() {
  const input = document.getElementById('cmtInput');
  const list = document.getElementById('bloggerCommentsList');
  if (input && input.value.trim() !== '' && list) {
    const div = document.createElement('div');
    div.className = 'comment-item';
    div.innerHTML = `
      <div class="comment-avatar"><i class="fa-solid fa-user"></i></div>
      <div class="comment-body">
        <div class="comment-user-meta">
          <span class="comment-username">Anonymous Reader</span>
          <span class="comment-time">Just now</span>
        </div>
        <p class="comment-text">${input.value.replace(/</g, "&lt;").replace(/>/g, "&gt;")}</p>
      </div>
    `;
    list.insertBefore(div, list.firstChild);
    input.value = '';
  }
}
//
